content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --success-color: #22c55e;
  --error-color: #ef4444;
  --bg-color: #f0fdf4;
  --card-bg: #ffffff;
  --text-color: #1f2937;
  --text-light: #4b5563;
  --border-radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #3b82f6;
    --primary-hover: #60a5fa;
    --success-color: #22c55e;
    --error-color: #ef4444;
    --bg-color: #111827;
    --card-bg: #1f2937;
    --text-color: #f9fafb;
    --text-light: #9ca3af;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.5), 0 2px 4px -1px rgba(0, 0, 0, 0.3);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.quiz-header {
  text-align: center;
  margin-bottom: 24px;
}

.quiz-header h1 {
  font-size: 1.8rem;
  color: #1e3a8a;
  margin-bottom: 8px;
}

@media (prefers-color-scheme: dark) {
  .quiz-header h1 {
    color: #60a5fa;
  }
}

.quiz-header p {
  color: var(--text-light);
  font-size: 0.95rem;
}

.quiz-card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  margin-bottom: 20px;
  transition: all 0.3s ease;
}

.quiz-card h2 {
  font-size: 1.25rem;
  margin-bottom: 20px;
  color: var(--text-color);
}

.options-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.option-btn {
  width: 100%;
  padding: 16px 18px;
  min-height: 52px; /* モバイルでの十分なタッチターゲットを確保 */
  text-align: left;
  background-color: #f9fafb;
  border: 2px solid #e5e7eb;
  border-radius: 8px;
  font-size: 1rem;
  color: var(--text-color);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  transform: scale(1);
}

@media (prefers-color-scheme: dark) {
  .option-btn {
    background-color: #374151;
    border-color: #4b5563;
  }
}

.option-btn:hover:not(:disabled) {
  background-color: #f3f4f6;
  border-color: #d1d5db;
  transform: translateY(-1px);
}

@media (prefers-color-scheme: dark) {
  .option-btn:hover:not(:disabled) {
    background-color: #4b5563;
    border-color: #6b7280;
  }
}

.option-btn:active:not(:disabled) {
  transform: scale(0.98);
}

.option-btn:disabled {
  cursor: default;
}

@keyframes popIn {
  0% { transform: scale(0.98); opacity: 0.8; }
  50% { transform: scale(1.02); }
  100% { transform: scale(1); opacity: 1; }
}

.option-btn.correct,
.correct {
  background-color: #dcfce7 !important;
  border-color: var(--success-color) !important;
  color: #166534 !important;
  font-weight: bold;
  animation: popIn 0.3s ease;
}

.option-btn.incorrect,
.incorrect {
  background-color: #fee2e2 !important;
  border-color: var(--error-color) !important;
  color: #991b1b !important;
  animation: popIn 0.3s ease;
}

@media (prefers-color-scheme: dark) {
  .option-btn.correct,
  .correct {
    background-color: rgba(34, 197, 94, 0.2) !important;
    color: #4ade80 !important;
  }
  .option-btn.incorrect,
  .incorrect {
    background-color: rgba(239, 68, 68, 0.2) !important;
    color: #f87171 !important;
  }
}

.next-btn {
  margin-top: 20px;
  width: 100%;
  padding: 14px;
  min-height: 48px;
  background-color: var(--primary-color);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.next-btn:hover {
  background-color: var(--primary-hover);
}

.next-btn:active {
  transform: scale(0.98);
}

.score-container {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
  padding: 32px 24px;
  width: 100%;
  text-align: center;
  transition: all 0.3s ease;
}

.score-container h2 {
  font-size: 1.8rem;
  color: #1e3a8a;
  margin-bottom: 16px;
}

@media (prefers-color-scheme: dark) {
  .score-container h2 {
    color: #60a5fa;
  }
}

.score-container p {
  font-size: 1.2rem;
  margin-bottom: 24px;
  color: var(--text-light);
}

.restart-btn {
  padding: 14px 32px;
  min-height: 48px;
  background-color: var(--success-color);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.restart-btn:hover {
  background-color: #16a34a;
}

.restart-btn:active {
  transform: scale(0.98);
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px;
  }

  .quiz-card {
    padding: 16px;
  }

  .quiz-header h1 {
    font-size: 1.5rem;
  }
}

/**
 * クイズの問題情報を表すインターフェース
 */
export interface Question {
  /** 問題の一意の識別子 */
  id: number;
  /** 問題文 */
  text: string;
  /** 選択肢の配列 */
  options: string[];
  /** 正解の選択肢のインデックス */
  correctAnswer: number;
  /** 問題の解説 */
  explanation: string;
  /** 問題の難易度 */
  difficulty?: 'easy' | 'medium' | 'hard';
}

/**
 * クイズの現在の状態を表すインターフェース
 */
export interface QuizState {
  /** 現在の問題のインデックス */
  currentQuestionIndex: number;
  /** 現在のスコア（正解数） */
  score: number;
  /** ユーザーが選択した選択肢のインデックス */
  selectedOption: number | null;
  /** すでに回答済みかどうか */
  isAnswered: boolean;
  /** クイズが終了したかどうか */
  isFinished: boolean;
}

import { useState } from 'react';
import { Question, QuizState } from './types';
import './index.css';

const questions: Question[] = [
  {
    id: 1,
    text: '日本で一番面積が大きい都道府県はどこでしょう？',
    options: ['岩手県', '北海道', '新潟県', '長野県'],
    correctAnswer: 1,
    explanation: '北海道は日本全国の約22%を占める最大の都道府県です。',
  },
  {
    id: 2,
    text: '日本最高峰である富士山の標高はどれくらいでしょう？',
    options: ['3,576m', '3,776m', '3,976m', '4,176m'],
    correctAnswer: 1,
    explanation: '富士山の標高は3,776mで、日本の最高峰です。',
  },
  {
    id: 3,
    text: '日本で一番長い川（全長）はどこでしょう？',
    options: ['利根川', '石狩川', '信濃川', '四万十川'],
    correctAnswer: 2,
    explanation: '信濃川は長野県から新潟県を流れ、日本で一番長い川（全長367km）です。',
  },
  {
    id: 4,
    text: '日本最大の湖「琵琶湖」がある都道府県はどこでしょう？',
    options: ['京都府', '大阪府', '滋賀県', '奈良県'],
    correctAnswer: 2,
    explanation: '琵琶湖は滋賀県にあり、日本で最も面積が広く、貯水量も最大の湖です。',
  },
  {
    id: 5,
    text: '日本最南端の有人島である島はどれでしょう？',
    options: ['石垣島', '西表島', '宮古島', '波照間島'],
    correctAnswer: 3,
    explanation: '波照間島は沖縄県八重山郡竹富町に属し、日本最南端の有人島です。',
  },
];

export default function App() {
  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0,
    score: 0,
    selectedOption: null,
    isAnswered: false,
    isFinished: false,
  });

  const handleOptionClick = (index: number) => {
    if (state.isAnswered) return;

    const currentQuestion = questions[state.currentQuestionIndex];
    const isCorrect = index === currentQuestion.correctAnswer;

    setState((prev) => ({
      ...prev,
      selectedOption: index,
      isAnswered: true,
      score: isCorrect ? prev.score + 1 : prev.score,
    }));
  };

  const handleNext = () => {
    const nextIndex = state.currentQuestionIndex + 1;
    if (nextIndex < questions.length) {
      setState((prev) => ({
        ...prev,
        currentQuestionIndex: nextIndex,
        selectedOption: null,
        isAnswered: false,
      }));
    } else {
      setState((prev) => ({
        ...prev,
        isFinished: true,
      }));
    }
  };

  const handleRestart = () => {
    setState({
      currentQuestionIndex: 0,
      score: 0,
      selectedOption: null,
      isAnswered: false,
      isFinished: false,
    });
  };

  const getScoreComment = (score: number, total: number) => {
    const rate = score / total;
    if (rate === 1) return 'お見事！パーフェクトです！';
    if (rate >= 0.8) return '素晴らしい！よくできました！';
    if (rate >= 0.6) return 'その調子です！もう少し！';
    return 'がんばりましょう！';
  };

  const currentQuestion = questions[state.currentQuestionIndex];
  const progressPercent = ((state.currentQuestionIndex + 1) / questions.length) * 100;

  return (
    <div className="app-container">
      <header className="quiz-header">
        <h1>日本地理クイズ</h1>
        <p>日本の地理に関する全5問のクイズに挑戦しよう！</p>
      </header>

      {!state.isFinished ? (
        <div className="quiz-card">
          <div
            style={{
              width: '100%',
              backgroundColor: '#e5e7eb',
              borderRadius: '8px',
              marginBottom: '16px',
              height: '8px',
              overflow: 'hidden',
            }}
          >
            <div
              style={{
                width: `${progressPercent}%`,
                backgroundColor: 'var(--primary-color)',
                height: '100%',
                transition: 'width 0.3s ease',
              }}
            />
          </div>

          <h2>
            第 {state.currentQuestionIndex + 1} 問 / 全 {questions.length} 問
          </h2>
          <p style={{ marginBottom: '16px', fontSize: '1.1rem', fontWeight: 'bold' }}>
            {currentQuestion.text}
          </p>
          <div className="options-container">
            {currentQuestion.options.map((option, index) => {
              let btnClass = 'option-btn';
              if (state.isAnswered) {
                if (index === currentQuestion.correctAnswer) {
                  btnClass += ' correct';
                } else if (index === state.selectedOption) {
                  btnClass += ' incorrect';
                }
              }

              return (
                <button
                  key={index}
                  className={btnClass}
                  onClick={() => handleOptionClick(index)}
                  disabled={state.isAnswered}
                >
                  {option}
                </button>
              );
            })}
          </div>

          {state.isAnswered && (
            <div
              style={{
                marginTop: '16px',
                padding: '12px',
                backgroundColor: '#f0fdf4',
                borderRadius: '8px',
                border: '1px solid #bbf7d0',
              }}
            >
              <p style={{ fontSize: '0.95rem', color: '#166534' }}>
                <strong>解説:</strong> {currentQuestion.explanation}
              </p>
            </div>
          )}

          {state.isAnswered && (
            <button className="next-btn" onClick={handleNext}>
              {state.currentQuestionIndex + 1 === questions.length ? '結果を見る' : '次の問題へ'}
            </button>
          )}
        </div>
      ) : (
        <div className="score-container">
          <h2>クイズ終了！</h2>
          <p style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#1e3a8a', marginBottom: '8px' }}>
            {getScoreComment(state.score, questions.length)}
          </p>
          <p>
            正解数: {state.score} / {questions.length} 問
          </p>
          <button className="restart-btn" onClick={handleRestart}>
            もう一度挑戦する
          </button>
        </div>
      )}
    </div>
  );
}
